script:
card({ name: "Timer", icon: 'timer' });
const words = {
  pick: "Pick a time to start",
  minutes: "{p0} min",
  done: "Time's up!",
  by: "Started by {p0}",
  stop: "Stop",
};

// One timer for the whole chat. Anyone can start or stop it.
// Draw the card again every second. This never sends anything.
every(1000);
const lengths = [1, 5, 10, 30];

function init() {
  return { ends: null, length: 0, by: '' };
}

on.start = (s, args, ctx) => {
  if (!lengths.includes(args.minutes)) return;
  s.length = args.minutes * 60000;
  s.ends = ctx.time + s.length;
  s.by = ctx.authorName;
};

on.stop = (s) => {
  s.ends = null;
};

function starts() {
  return row(lengths.map(m => button(words.minutes.replace('{p0}', m), 'start', { minutes: m }, { tone: 'accent' })), { align: 'center' });
}

function view(s, me, now) {
  if (s.ends === null) return column([text(words.pick, { tone: 'muted', align: 'center' }), starts()]);
  const left = Math.max(0, s.ends - now);
  const secs = Math.ceil(left / 1000);
  const pad = n => String(n).padStart(2, '0');
  const parts = [];
  if (left === 0) parts.push(text(words.done, { size: 'large', bold: true, align: 'center', tone: 'success' }));
  else parts.push(text(pad(Math.floor(secs / 60)) + ':' + pad(secs % 60), { size: 'huge', bold: true, align: 'center', tone: 'accent' }));
  parts.push(progress(left / s.length));
  parts.push(text(words.by.replace('{p0}', s.by), { size: 'small', tone: 'muted', align: 'center' }));
  parts.push(left === 0 ? starts() : button(words.stop, 'stop', null, { tone: 'muted', align: 'center' }));
  return column(parts);
}
